css:
.d-checkbox-draw{position:relative;display:inline-flex;align-items:center;gap:var(--sp-8);font-family:var(--sans);outline:none;cursor:pointer}
.d-cd-input{position:absolute;inset:0;width:100%;height:100%;margin:0;opacity:0;cursor:pointer}
.d-cd-box{position:relative;width:22px;height:22px;border:1px solid var(--line);border-radius:2px;background:var(--paper);box-shadow:inset 0 1px 0 #fff5}
.d-checkbox-draw:hover .d-cd-box{border-color:var(--ink)}
.d-cd-tick{position:absolute;inset:0;width:22px;height:22px;fill:none;stroke-linecap:square;stroke-linejoin:miter}
.d-cd-ink,.d-cd-bleed{stroke:var(--ink);stroke-width:1;stroke-dasharray:1;stroke-dashoffset:1}
.d-cd-bleed{opacity:.4;transform:translate(1px,1px)}
.d-cd-input:checked + .d-cd-box .d-cd-ink{animation:d-checkbox-draw-ink 280ms cubic-bezier(.2,.75,.25,1) both}
.d-cd-input:checked + .d-cd-box .d-cd-bleed{animation:d-checkbox-draw-bleed 280ms cubic-bezier(.2,.75,.25,1) 120ms both}
.d-cd-input:focus-visible + .d-cd-box{outline:1px solid var(--ink);outline-offset:2px}
.d-checkbox-draw .d-cd-text{font-size:var(--fs-13);color:var(--ink)}
@keyframes d-checkbox-draw-ink{to{stroke-dashoffset:0}}
@keyframes d-checkbox-draw-bleed{to{stroke-dashoffset:0}}
